package io.github.jaruizes.proposal.infrastructure.api.rest; import io.github.jaruizes.proposal.domain.exceptions.DomainException; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.Map; @RestControllerAdvice public class ApiExceptionHandler {@ExceptionHandler({DomainException.class,IllegalArgumentException.class}) ResponseEntity<?> badRequest(RuntimeException ex){return ResponseEntity.badRequest().body(Map.of("error",ex.getMessage()));}}
